package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"

	"github.com/jteeuwen/go-bindata-asset/go/bindata"
)

// Define the structure for parsing the Go code.
type StructDefinition struct {
	Name  string   // Name of the struct
	Fields []Field  // List of field definitions
}

// A Field represents a single field within the struct.
type Field struct {
	Type    string     // Type of the field
	Name    string     // Name of the field
	Offset  int        // Offset in bytes
	Size    int        // Size of the field in bytes
	Nullable bool      // Nullable (true if it's optional)
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run parser.go <input_file> <output_filename>")
		os.Exit(1)
	}

	inputFile := os.Args[1]
	outputFilename := os.Args[2]

	// Parse the Go file into AST nodes.
	file, err := parser.ParseFile(token.NewFileSet(), inputFile, nil, parser.ParseComments)
	if err != nil {
		fmt.Printf("Error parsing %s: %v\n", inputFile, err)
		return
	}

	// Extract the type and fields information from the AST.
	var structs []*StructDefinition
	for _, node := range file.Nodes {
		if n, ok := node.(*ast.StructType); ok && n.Fields != nil {
			structName := filepath.Base(inputFile)
			fieldDefs := make([]Field, 0, len(n.Fields))
			for _, f := range n.Fields.List {
				fDef := Field{
					Type:    fmt.Sprintf("%T", f.Type),
					Name:    f.Name.Name,
					Offset:  f.Offset,
					Size:    byteSize(f.Type),
					Nullable: !f.Type.ImplementsInterface(ast.Interface{}),
				}
				if f.Type == nil || f.Type.Kind() != reflect.Ptr {
					fDef.Nullable = false
				} else {
					fDef.Nullable = true
				}
				fieldDefs = append(fieldDefs, fDef)
			}
			structs = append(structs, &StructDefinition{Name: structName, Fields: fieldDefs})
		}
	}

	// Generate Avro schema.
	schema := generateAvroSchema(&structs[0])
	writeToFile(schema, outputFilename+".avsc")
}

// Generates an Avro schema using the provided StructDefinition.
func generateAvroSchema(def *StructDefinition) string {
	var buf bytes.Buffer
	fmt.Fprintf(&buf, "title: '%s'\n", def.Name)
	fmt.Fprintf(&buf, "namespace: 'com.example'\n")

	// Add top-level objects as needed.
	topLevelObjects := map[string]string{}
	topLevelObjects["schema"] = def.Name

	// Write the schema to a file.
	return bindata.Write(&bindata.Options{Filename: outputFilename}.Add(topLevelObjects))
}

// Writes the generated Avro schema to a specified file.
func writeToFile(content interface{}, filename string) error {
	file, err := os.Create(filename)
	if err != nil {
		return err
	}
	defer file.Close()

	if err := json.NewEncoder(file).Encode(content); err != nil {
		return err
	}

	return nil
}

